const categories = ['Roads & Potholes','Garbage & Sanitation','Water Supply','Drainage','Streetlights','Public Infrastructure','Traffic & Public Spaces','Other'];
const statuses = ['Submitted','Under Review','Assigned','In Progress','Resolved','Reopened'];
let csrfToken = ''; let currentUser = null; let page = 'overview'; let cachedComplaints = []; let selectedCoordinates = null; let adminMapInstance = null; let publicMapInstance = null;
let currentLang = (() => { try { return localStorage.getItem('ss-language') === 'hi' ? 'hi' : 'en'; } catch (_) { return 'en'; } })();
const localized = value => window.SamadhanI18n ? window.SamadhanI18n.localized(value,currentLang) : String(value ?? '');
function translateDOM(root=document.body){ if(window.SamadhanI18n) window.SamadhanI18n.translateDOM(root,currentLang); }
function refreshLanguageButtons(){
 document.documentElement.lang=currentLang==='hi'?'hi':'en';
 const en=$('#langEn'),hi=$('#langHi');
 if(en){en.classList.toggle('selected',currentLang==='en');en.setAttribute('aria-pressed',String(currentLang==='en'));}
 if(hi){hi.classList.toggle('selected',currentLang==='hi');hi.setAttribute('aria-pressed',String(currentLang==='hi'));}
 document.title=currentLang==='hi'?'समाधान साथी — भारत नागरिक सेवा':'Samadhan Sathi — India Civic Tech';
}
async function setLanguage(lang){
 currentLang=lang==='hi'?'hi':'en';
 try{localStorage.setItem('ss-language',currentLang)}catch(_){}
 refreshLanguageButtons();
 translateDOM(document.body);
 await go(page);
 translateDOM(document.body);
}
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = value => value ? new Intl.DateTimeFormat(currentLang==='hi'?'hi-IN':'en-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)) : '—';
const statusClass = s => 's-' + String(s || 'Submitted').replaceAll(' ','-');
const status = s => `<span class="status ${statusClass(s)}">${esc(localized(s))}</span>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3200)}
async function api(path, options={}){const method=(options.method||'GET').toUpperCase();const headers={...(options.headers||{})};if(options.body && typeof options.body!=='string'){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}if(!['GET','HEAD','OPTIONS'].includes(method)&&csrfToken)headers['X-CSRF-Token']=csrfToken;let response;try{response=await fetch('/api'+path,{...options,method,headers,credentials:'same-origin'})}catch(networkError){throw new Error('Cannot reach the website backend. In the project folder, run `python server.py` and open http://127.0.0.1:3000. Do not open public/index.html by double-clicking it.')}if(response.status===204)return null;let payload={};try{payload=await response.json()}catch{}if(response.status===401&&path!='/auth/login'&&path!='/auth/register'){currentUser=null;syncProfile()}if(!response.ok)throw new Error(payload.error||`Request failed (${response.status})`);if(payload.csrfToken)csrfToken=payload.csrfToken;return payload}
function syncProfile(){const name=currentUser?.name||'Guest';$('#profileName').textContent=name;$('#profileRole').textContent=currentUser?(currentUser.role==='admin'?'Administrator':'Citizen account'):'Not signed in';$('#avatar').textContent=currentUser?name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase():'?';$('#authBtn').textContent=currentUser?'Sign out':'Sign in';$('#adminNav').classList.toggle('hidden',currentUser?.role!=='admin');$('#auditNav').classList.toggle('hidden',currentUser?.role!=='admin')}
function pageHead(k,title,desc,action=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h2>${title}</h2><p>${desc}</p></div>${action}</div>`}
function cardStat(label,value,foot){return `<div class="card stat"><div class="statlabel">${label}</div><div class="statvalue">${value}</div><div class="statfoot">${foot}</div></div>`}
function priorityBadge(level){const p=['Critical','High','Medium','Low'].includes(level)?level:'Medium';return `<span class="priority priority-${p.toLowerCase()}">${esc(localized(p))}</span>`}
function tableRows(list,admin=false){if(!list.length)return `<tr><td colspan="7"><div class="empty">No complaints found.</div></td></tr>`;return list.map(c=>`<tr><td><span class="ref">${esc(c.referenceId)}</span></td><td><b>${esc(c.title)}</b><span class="subline">${esc(c.locality)}</span></td><td>${esc(localized(c.category))}</td><td>${priorityBadge(c.priority)}</td><td>${date(c.createdAt)}</td><td>${status(c.status)}</td><td>${admin?`<button class="linkbtn" data-review="${esc(c.referenceId)}">Review →</button>`:`<button class="linkbtn" data-detail="${esc(c.referenceId)}">View →</button>`}</td></tr>`).join('')}
function table(list,admin=false){return `<div class="card tablewrap"><table><thead><tr><th>Reference</th><th>Issue</th><th>Category</th><th>Priority</th><th>Submitted</th><th>Status</th><th>Action</th></tr></thead><tbody>${tableRows(list,admin)}</tbody></table></div>`}
function signedOutPrompt(){return `<div class="card panel"><h3>Sign in to continue</h3><p style="color:var(--muted);font-size:12px">Your complaints are private. Sign in or create a citizen account to submit and track reports.</p><button class="primary" id="signInInline">Sign in / Create account</button></div>`}
